:root {
  --bg: #1a1c2c;
  --card: #2a2e4a;
  --text: #f4f4f4;
  --accent: #ffcd75;
  --accent-dark: #c49a4a;
  --correct: #38b764;
  --wrong: #b13e53;
  --border: #5d275d;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: linear-gradient(45deg, var(--border) 25%, transparent 25%, transparent 75%, var(--border) 75%),
                    linear-gradient(45deg, var(--border) 25%, transparent 25%, transparent 75%, var(--border) 75%);
  background-size: 32px 32px;
  background-position: 0 0, 16px 16px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 8px 8px 0 var(--border);
  text-align: center;
}

h1 {
  font-size: 2rem;
  margin-bottom: 16px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  word-break: break-word;
}

.score-label {
  font-size: 1.1rem;
  margin-bottom: 24px;
  color: var(--text);
}

#score {
  font-weight: bold;
  color: var(--accent);
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: bold;
  padding: 12px 28px;
  border: 3px solid var(--accent);
  border-radius: 0;
  background: var(--bg);
  color: var(--text);
  cursor: pointer;
  transition: transform 0.05s, background 0.15s;
  min-width: 80px;
}

button:hover:not(:disabled) {
  background: var(--accent-dark);
  color: var(--bg);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

button:active:not(:disabled) {
  transform: translate(2px, 2px);
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

button.correct {
  background: var(--correct);
  border-color: var(--correct);
  color: #fff;
}

button.wrong {
  background: var(--wrong);
  border-color: var(--wrong);
  color: #fff;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

#next {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
}

#next:hover:not(:disabled) {
  background: var(--accent-dark);
}

#next:disabled {
  opacity: 0.4;
}

#restart {
  background: transparent;
  border-color: var(--text);
  color: var(--text);
}

#restart:hover {
  background: var(--text);
  color: var(--bg);
}

@media (max-width: 400px) {
  h1 { font-size: 1.5rem; }
  button { font-size: 1.1rem; padding: 10px 20px; }
  .card { padding: 24px 16px; }
}

const questions = [
  { text: '2 + 2 = ?', answers: ['4', '5'], correct: 0 },
  { text: '3 + 3 = ?', answers: ['5', '6'], correct: 1 }
];

let current = 0;
let score = 0;
let answered = false;

const questionEl = document.getElementById('question');
const scoreEl = document.getElementById('score');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

function render() {
  const q = questions[current];
  questionEl.textContent = q.text;
  answerA.textContent = q.answers[0];
  answerB.textContent = q.answers[1];
  answerA.setAttribute('aria-label', 'Answer A: ' + q.answers[0]);
  answerB.setAttribute('aria-label', 'Answer B: ' + q.answers[1]);
  answerA.disabled = false;
  answerB.disabled = false;
  answerA.classList.remove('correct', 'wrong');
  answerB.classList.remove('correct', 'wrong');
  answered = false;
  nextBtn.disabled = true;
}

function handleAnswer(index) {
  if (answered) return;
  answered = true;
  const q = questions[current];
  const buttons = [answerA, answerB];
  buttons.forEach((btn, i) => {
    btn.disabled = true;
    if (i === q.correct) btn.classList.add('correct');
    else if (i === index) btn.classList.add('wrong');
  });
  if (index === q.correct) {
    score += 1;
    scoreEl.textContent = score;
  }
  nextBtn.disabled = false;
}

answerA.addEventListener('click', () => handleAnswer(0));
answerB.addEventListener('click', () => handleAnswer(1));

nextBtn.addEventListener('click', () => {
  if (current < questions.length - 1) {
    current += 1;
    render();
  } else {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
  }
});

restartBtn.addEventListener('click', () => {
  current = 0;
  score = 0;
  scoreEl.textContent = score;
  render();
});

render();
